const sections = Object.entries(PROPS).map(([g, list]) => { total += list.length; return `<section style="display: flex; flex-direction: column; gap: 12px"><div style="font: 700 22px Fredoka, sans-serif; color: #C93F6E">${g} <span style="font: 800 14px Nunito, sans-serif; color: #7A5A6E">${list.length}</span></div><div style="display: grid; grid-template-columns: repeat(10, minmax(0, 1fr)); gap: 14px 8px">${list.map(([n, s]) => cell(n, s)).join('')}</div></section>`; }).join('');
